// EQ-9a (BL-084): el equipo real de la ficha (GNBldItems.sheet) a lo que pide encode(). Puro.
// view = GNBldItems.sheet() o null; b = la build ({ code, mode: 'pve'|'wvw'|'pvp', sub }). null si no hay código.
// En PvP el amuleto se elige en el juego: AE2 lleva solo armas y sigilos.
var FROM_SLOT = { 'Casco': ['Helm'], 'Hombreras': ['Shoulders'], 'Pecho': ['Coat'], 'Guantes': ['Gloves'], 'Perneras': ['Leggings'], 'Botas': ['Boots'],
  'Espalda': ['Backpack'], 'Accesorio': ['Accessory1', 'Accessory2'], 'Amuleto': ['Amulet'], 'Anillo': ['Ring1', 'Ring2'] };
var FROM_WEAPON = { LongBow: 'Longbow', ShortBow: 'Shortbow', Harpoon: 'Spear' };
function modeOf(b) {
  var m = String((b && b.mode) || '').toLowerCase(), s = String((b && b.sub) || '').toLowerCase();
  if (m === 'wvw') return 'WvW';
  if (m === 'pvp') return 'PvP';
  if (s === 'raids') return 'Raid';
  if (s === 'fractals') return 'Fractal';
  return 'PvE';
}
function fromSheet(view, b) {
  if (!b || !b.code) return null;
  var out = { code: b.code, mode: modeOf(b), gear: {}, runeId: 0, relicId: 0 };
  if (!view) return out;
  var sid = function (s) { return s && !s.missing && s.id ? s.id : 0; };
  var used = {};
  var put = function (label, statId) {
    var k = (FROM_SLOT[label] || []).filter(function (x) { return !used[x]; })[0];
    if (!k || !statId) return;
    used[k] = 1; out.gear[k] = { statId: statId };
  };
  (view.armor || []).forEach(function (r) { put(r.slot, sid(r.stat)); });
  (view.trinkets || []).forEach(function (r) { put(r.slot, sid(r.stat)); });
  if (view.rune && view.rune.id) out.runeId = view.rune.id;
  else if (view.runeMixed) {
    var n = {}, best = 0;
    (view.armor || []).forEach(function (r) {
      var id = r.rune && r.rune.id;
      if (!id) return;
      n[id] = (n[id] || 0) + 1;
      if (!best || n[id] > n[best]) best = id;
    });
    out.runeId = best;
  }
  if (view.relic && view.relic.id) out.relicId = view.relic.id;
  (view.sets || []).forEach(function (set) {
    var pre = String(set.n) === '1' ? 'WeaponA' : String(set.n) === '2' ? 'WeaponB' : '';
    if (!pre) return;
    (set.hands || []).forEach(function (h) {
      var sub = (h.item && h.item.sub) || '', wt = FROM_WEAPON[sub] || sub;
      if (!wt || !weaponId(wt)) wt = '';
      var sg = (h.sigils || []).filter(function (x) { return x && x.id; }).map(function (x) { return x.id; });
      var g = { statId: sid(h.stat) };
      if (wt) g.weaponType = wt;
      if (sg[0]) g.sigilId = sg[0];
      if (sg[1]) g.sigil2Id = sg[1];
      if (g.statId || g.weaponType || g.sigilId) out.gear[pre + (h.hand === 'o' ? '2' : '1')] = g;
    });
  });
  return out;
}
// El AE2 de la ficha, o '' si no se puede (sin código o código inválido).
function fromSheetCode(view, b) {
  var x = fromSheet(view, b);
  if (!x) return '';
  try { return encode(x); } catch (_) { return ''; }
}

test('EQ-9a: fromSheet pasa el equipo real de la ficha (GNBldItems.sheet) a AE2', () => {
  const st = (id, missing) => ({ id, name: 'x', attrs: [], missing });
  const view = {
    armor: ['Casco', 'Hombreras', 'Pecho', 'Guantes', 'Perneras', 'Botas'].map((s, i) => ({ slot: s, item: { id: 10 + i }, stat: st(i === 2 ? 1066 : 1077, i === 5), rune: { id: i < 4 ? 24836 : 24800 } })),
    rune: null, runeMixed: true,
    trinkets: ['Espalda', 'Accesorio', 'Accesorio', 'Amuleto', 'Anillo', 'Anillo'].map((s) => ({ slot: s, item: { id: 1 }, stat: st(1077) })),
    relic: { id: 100916 }, amulet: null,
    sets: [{ n: 1, hands: [{ hand: 'm', item: { sub: 'LongBow' }, stat: st(1077), sigils: [{ id: 24615 }, { id: 24868 }] }] },
      { n: 2, hands: [{ hand: 'm', item: { sub: 'Sword' }, stat: st(1077), sigils: [{ id: 24618 }] }, { hand: 'o', item: { sub: 'Harpoon' }, stat: null, sigils: [{ id: 24615, missing: true }] }] }]
  };
  const x = A.fromSheet(view, { code: LINK, mode: 'pve', sub: 'raids' });
  assert.equal(x.mode, 'Raid');
  assert.equal(x.runeId, 24836, 'runas mezcladas: la de más piezas');
  assert.equal(x.relicId, 100916);
  assert.equal(x.gear.Coat.statId, 1066);
  assert.equal(x.gear.Boots, undefined, 'estadística que la API no conoce: no la invento');
  assert.equal(x.gear.Accessory2.statId, 1077, 'el segundo accesorio va al segundo casillero');
  assert.equal(x.gear.Ring2.statId, 1077);
  assert.deepEqual(x.gear.WeaponA1, { statId: 1077, weaponType: 'Longbow', sigilId: 24615, sigil2Id: 24868 });
  assert.deepEqual(x.gear.WeaponB2, { statId: 0, weaponType: 'Spear', sigilId: 24615 });
  const d = A.decode(A.fromSheetCode(view, { code: LINK, mode: 'pve', sub: 'raids' }));
  assert.equal(d.code, LINK);
  assert.equal(d.mode, 'Raid');
  assert.equal(Object.keys(d.gear).length, 14);
  assert.equal(d.gear.WeaponA1.weaponType, 'Longbow');
  assert.equal(d.runeId, 24836);
  // modos y casos límite
  assert.equal(A.modeOf({ mode: 'pve', sub: 'fractals' }), 'Fractal');
  assert.equal(A.modeOf({ mode: 'pve', sub: 'open-world' }), 'PvE');
  assert.equal(A.modeOf({ mode: 'wvw', sub: 'zerg' }), 'WvW');
  assert.equal(A.modeOf({ mode: 'pvp' }), 'PvP');
  assert.equal(A.fromSheet(view, {}), null, 'sin código, nada');
  assert.deepEqual(A.fromSheet(null, { code: LINK, mode: 'pvp' }), { code: LINK, mode: 'PvP', gear: {}, runeId: 0, relicId: 0 });
  assert.equal(A.fromSheetCode(view, { code: 'basura' }), '', 'código inválido: vacío, sin lanzar');
  const pvp = A.decode(A.fromSheetCode({ armor: [], trinkets: [], sets: view.sets, relic: null, amulet: { id: 8 } }, { code: LINK, mode: 'pvp' }));
  assert.equal(pvp.mode, 'PvP');
  assert.deepEqual(Object.keys(pvp.gear), ['WeaponA1', 'WeaponB1', 'WeaponB2'], 'en PvP, solo armas y sigilos (el amuleto se elige en el juego)');
});

// EQ-9a: copiar la build en AE2 (Alter Ego) con el equipo real: aparece cuando el equipo ya llegó.
function ae2BtnHTML(m) {
  var A = root.GNBldAe2;
  if (!A || typeof A.fromSheetCode !== 'function' || !m || !m.gear || !m.b) return '';
  if (m.b.mine && !m.b.base) return '';
  return '<button type="button" class="bld-btn" data-sheet="ae2" title="Con estadísticas, runa, sigilos y reliquia, para el complemento Alter Ego">Copiar AE2 (Alter Ego)</button>';
}

// EQ-9a: el AE2 de la build que se está viendo, con el equipo ya traído ('' si no se puede).
function ae2Code() {
  var b = current(), A = root.GNBldAe2;
  if (!b || !A || typeof A.fromSheetCode !== 'function') return '';
  return A.fromSheetCode(st.gear[b.id] || null, { code: b.code, mode: b.mode, sub: b.sub });
}
function ae2Act(ctx) {
  var code = ae2Code(), toast = function (m, kind) { if (ctx && ctx.toast) ctx.toast(m, kind); };
  if (!code) { toast('No pude armar el código AE2 de esta build.', 'err'); return 'ae2'; }
  Promise.resolve(S() ? S().copy(code) : false).then(function (ok) {
    toast(ok ? 'AE2 copiado: pegalo en Alter Ego (Build Library → Import).' : 'No pude copiar el AE2: probá de nuevo.', ok ? 'ok' : 'err');
  });
  return 'ae2';
}

test('EQ-9a: «Copiar AE2 (Alter Ego)» con el equipo real de la ficha', async () => {
  globalThis.GNBldAe2 = require('../js/bld-ae2.js');
  const I = globalThis.GNBldItems, C = globalThis.GNBldCode;
  const b = CAT.builds.find((x) => GEAR[x.id] && GEAR[x.id].armor && GEAR[x.id].relic && x.mode === 'pve' && x.sub === 'raids');
  const e = GEAR[b.id], need = I.ids(e);
  const R = { items: Object.fromEntries(need.items.map((id) => [id, { id, name: 'x', icon: '', type: 'Weapon', sub: 'Sword' }])),
    stats: Object.fromEntries(need.stats.map((id) => [id, { id, name: 'S' + id, attrs: [] }])), amulets: {} };
  const v = I.sheet(e, R);
  globalThis.GNBldLib = fakeLib([b]);
  assert.doesNotMatch(P.sheetHTML({ b, nav: P.navOf([b], b.id), gear: undefined }), /data-sheet="ae2"/, 'sin equipo todavía, sin botón');
  assert.doesNotMatch(P.sheetHTML({ b, nav: P.navOf([b], b.id), gear: null }), /data-sheet="ae2"/, 'build sin equipo, sin botón');
  assert.match(P.sheetHTML({ b, nav: P.navOf([b], b.id), gear: v }), /<button type="button" class="bld-btn" data-sheet="ae2"[^>]*>Copiar AE2 \(Alter Ego\)<\/button>/);
  assert.equal(P.ae2BtnHTML({ b: { mine: {}, base: null }, gear: v }), '', 'propia sin build de base: el AE2 sale del Editor');
  SH._state.id = b.id; SH._state.gear[b.id] = v;
  const d = globalThis.GNBldAe2.decode(P.ae2Code());
  assert.equal(d.code, C.encode(C.decode(b.code)));
  assert.equal(d.mode, 'Raid');
  assert.equal(d.relicId, e.relic);
  if (e.rune) assert.equal(d.runeId, e.rune);
  assert.equal(d.gear.Helm.statId, e.armor[0][1]);
  const w1 = (e.weapons || []).find((w) => w[0] === 1 && w[1] === 'm');
  if (w1) {
    assert.equal(d.gear.WeaponA1.weaponType, 'Sword');
    if (w1[4] && w1[4][0]) assert.equal(d.gear.WeaponA1.sigilId, w1[4][0]);
  }
  const toasts = [];
  const ctx = { go() {}, toast: (m, k) => toasts.push(k + ':' + m) };
  assert.equal(P.onClick(ctx, { target: el({ 'data-sheet': 'ae2' }) }), 'ae2');
  await new Promise((r) => setTimeout(r, 0));
  await new Promise((r) => setTimeout(r, 0));
  assert.equal(toasts.length, 1);
  assert.match(toasts[0], /AE2/);
  delete globalThis.GNBldAe2;
  assert.equal(P.ae2Code(), '', 'sin el módulo, nada');
  assert.doesNotMatch(P.sheetHTML({ b, nav: P.navOf([b], b.id), gear: v }), /data-sheet="ae2"/, 'sin el módulo, sin botón');
  delete SH._state.gear[b.id];
  delete globalThis.GNBldLib;
});
